sys_variable_value.value:
(function execute(inputs, outputs) {
    var hiraUtil = new x_hccc_hoc_ohs.HoCOHSMHIRAUtils();

    if(inputs.previousHira){
         outputs.hira_record = hiraUtil.copyCase(inputs.previousHira);
    }else if(inputs.position){
        outputs.hira_record = hiraUtil.createCase(inputs.position);
    }

    
})(inputs, outputs);

